import pytest
from isort.parse import file_contents
from isort.settings import DEFAULT_CONFIG, Config


def test_file_contents_comprehensive():
    # Covers:
    # - old_finders=True vs False
    # - Trailing newline adjustment
    # - isort:imports- / isort: imports- tags
    # - float_to_top with comments, parentheses, multi-line blocks
    # - Semicolon separated statements
    # - type_of_import == "from" with len(line_parts) == 2 and comments
    # - parentheses spanning multiple lines, new_comment handling, nested_comments
    # - backslash line continuation with new_comment and parentheses check
    # - import vs cimport parts splitting
    # - "as" aliases in straight and from imports, remove_redundant_aliases
    # - verbose and only_modified config options
    # - empty placed_module warning (MissingSection raising or fallback section)
    # - force_single_line with comments and attach_comments_to
    # - above comments popping into categorized_comments["above"]
    # - trailing commas capturing
    # - else block comment attachments and straight imports updating

    content = (
        "# isort:imports-FIRST_PARTY\n"
        "# Above comment 1\n"
        "# Above comment 2\n"
        "import sys, os\n"
        "from foo import (a as a, b,\n"
        "    c as c) # nested comment b\n"
        "from bar import \\\n"
        "    (d,\n"
        "    e)\n"
        "import baz as baz\n"
        "import qux as other_qux\n"
        "import unmatched_mod\n"
        "some_code = 1; another_code = 2\n"
        "# isort: imports-THIRD_PARTY\n"
    )

    config = DEFAULT_CONFIG
    parsed = file_contents(content, config=config)
    assert parsed is not None
    assert parsed.change_count <= 0

    # Test with old_finders=True and empty placed_module warning path with valid section
    config_old = Config(
        old_finders=True,
        verbose=False,
        sections=("FIRST_PARTY", "UNKNOWN_SECTION", "STANDARD_LIBRARY", "THIRD_PARTY"),
        known_first_party=("unknown_custom_module_xyz",),
    )
    parsed_old = file_contents("import unknown_custom_module_xyz\n", config=config_old)
    assert parsed_old is not None

    # Test trailing backslash with trailing comment and single-line from import comment
    content_comments = (
        "from foo import x # comment on x\n"
        "import alpha \\\n"
        "  beta\n"
    )
    parsed_comments = file_contents(content_comments, config=Config(verbose=True, only_modified=True))
    assert parsed_comments is not None

    # Test space/cimport path and trailing comma
    content_cimport = "from foo cimport a, b,\n"
    parsed_cimport = file_contents(content_cimport, config=Config())
    assert parsed_cimport is not None
